/// The `PT_*` name of a segment type, on `machine`.
pub fn segment_type(machine: u16, v: u64) -> Option<&'static str> {
    let specific = match machine {
        0x8 => match v {
            0x70000000 => Some("PT_MIPS_REGINFO"),
            0x70000001 => Some("PT_MIPS_RTPROC"),
            0x70000002 => Some("PT_MIPS_OPTIONS"),
            0x70000003 => Some("PT_MIPS_ABIFLAGS"),
            _ => None,
        },
        0x28 => match v {
            0x70000000 => Some("PT_ARM_ARCHEXT"),
            0x70000001 => Some("PT_ARM_EXIDX"),
            _ => None,
        },
        0xb7 => match v {
            0x70000002 => Some("PT_AARCH64_MEMTAG_MTE"),
            _ => None,
        },
        0xf3 => match v {
            0x70000003 => Some("PT_RISCV_ATTRIBUTES"),
            _ => None,
        },
        _ => None,
    };
    if specific.is_some() {
        return specific;
    }
    Some(match v {
        0x0 => "PT_NULL",
        0x1 => "PT_LOAD",
        0x2 => "PT_DYNAMIC",
        0x3 => "PT_INTERP",
        0x4 => "PT_NOTE",
        0x5 => "PT_SHLIB",
        0x6 => "PT_PHDR",
        0x7 => "PT_TLS",
        0x60000000 => "PT_LOOS",
        0x6464e550 => "PT_SUNW_UNWIND",
        0x6474e550 => "PT_GNU_EH_FRAME",
        0x6474e551 => "PT_GNU_STACK",
        0x6474e552 => "PT_GNU_RELRO",
        0x6474e553 => "PT_GNU_PROPERTY",
        0x6474e554 => "PT_GNU_SFRAME",
        0x65a3dbe5 => "PT_OPENBSD_MUTABLE",
        0x65a3dbe6 => "PT_OPENBSD_RANDOMIZE",
        0x65a3dbe7 => "PT_OPENBSD_WXNEEDED",
        0x65a3dbe8 => "PT_OPENBSD_NOBTCFI",
        0x65a3dbe9 => "PT_OPENBSD_SYSCALLS",
        0x65a41be6 => "PT_OPENBSD_BOOTDATA",
        0x6fffffff => "PT_HIOS",
        0x70000000 => "PT_LOPROC",
        0x7fffffff => "PT_HIPROC",
        _ => return None,
    })
}

/// The `SHF_*` flags of sections on `machine`, by bit.
pub fn section_flags(machine: u16) -> Vec<(&'static str, u64)> {
    let mut out = vec![
        ("SHF_WRITE", 0x1),
        ("SHF_ALLOC", 0x2),
        ("SHF_EXECINSTR", 0x4),
        ("SHF_MERGE", 0x10),
        ("SHF_STRINGS", 0x20),
        ("SHF_INFO_LINK", 0x40),
        ("SHF_LINK_ORDER", 0x80),
        ("SHF_OS_NONCONFORMING", 0x100),
        ("SHF_GROUP", 0x200),
        ("SHF_TLS", 0x400),
        ("SHF_COMPRESSED", 0x800),
        ("SHF_GNU_RETAIN", 0x200000),
        ("SHF_EXCLUDE", 0x80000000),
        ("SHF_SUNW_NODISCARD", 0x100000),
    ];
    match machine {
        0x8 => out.extend([
            ("SHF_MIPS_NODUPES", 0x1000000),
            ("SHF_MIPS_NAMES", 0x2000000),
            ("SHF_MIPS_LOCAL", 0x4000000),
            ("SHF_MIPS_NOSTRIP", 0x8000000),
            ("SHF_MIPS_GPREL", 0x10000000),
            ("SHF_MIPS_MERGE", 0x20000000),
            ("SHF_MIPS_ADDR", 0x40000000),
            ("SHF_MIPS_STRING", 0x80000000),
        ]),
        0x28 => out.extend([("SHF_ARM_PURECODE", 0x20000000)]),
        0x3e => out.extend([("SHF_X86_64_LARGE", 0x10000000)]),
        0xa4 => out.extend([("SHF_HEX_GPREL", 0x10000000)]),
        0xb7 => out.extend([("SHF_AARCH64_PURECODE", 0x20000000)]),
        _ => {}
    }
    out
}

